// GENERATED by scripts/build.js from lib/resources/model.js. Edit that file, then run `npm run build`.
/**
 * Resources: the data model shared by the public site (server.js -> resources.js) and the admin
 * service (admin/). One Firestore document per resource, collection `resources`, doc id = a short
 * random id that never changes (it is in the frame URL and the bucket paths).
 *
 * scripts/build.js copies lib/resources/ into admin/lib/resources/ (the admin service is deployed
 * from admin/ on its own). Edit the files here, then run `npm run build`.
 */
"use strict";

const crypto = require("node:crypto");

const SITE = "https://josediaztutoring.com";
const LANGS = ["en", "es"];
const BASE = { en: "/resources/", es: "/es/recursos/" };

const SUBJECTS = {
  algebra: { en: "Algebra", es: "Álgebra" },
  "geometry-trig": { en: "Geometry & trig", es: "Geometría y trigonometría" },
  precalc: { en: "Precalculus", es: "Precálculo" },
  calculus: { en: "Calculus", es: "Cálculo" },
  physics: { en: "Physics", es: "Física" },
  circuits: { en: "Circuits", es: "Circuitos" },
  "digital-logic": { en: "Digital logic", es: "Lógica digital" },
  programming: { en: "Programming", es: "Programación" },
  embedded: { en: "Embedded systems", es: "Sistemas embebidos" },
  other: { en: "Other", es: "Otros" },
};
const LEVELS = {
  "high-school": { en: "High school", es: "High school" },
  college: { en: "College", es: "Universidad" },
  engineering: { en: "Engineering", es: "Ingeniería" },
};
// pages a resource can point to as "related exam page" (the exam calendar pages in scripts/build.js)
const EXAM_LINKS = [
  { en: "/exams/", es: "/es/examenes/", label: { en: "Exam calendar", es: "Calendario de exámenes" } },
  { en: "/exams/algebra-1-eoc/", es: "/es/examenes/eoc-algebra-1/", label: { en: "Algebra 1 EOC guide", es: "Guía del EOC de Álgebra 1" } },
];
const STATUSES = ["draft", "published", "unpublished"];
const VISIBILITIES = ["public"]; // later: "unlisted", "private"; any other value -> 404 for now
const RESERVED_SLUGS = new Set(["og", "katex"]); // /resources/og/<card>.png, /resources/katex/<version>/...
const DESC_MAX = 155;
const SLUG_MAX = 80;
const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const ID_RE = /^[a-z0-9]{10}$/;
// PDF files attached to a resource (/resources/<slug-en>/files/<name>): the name as uploaded, case kept.
// No leading dot (so no "..pdf" or hidden names); everything else as in the spec.
const FILE_NAME_RE = /^(?!\.)[A-Za-z0-9._-]+\.pdf$/;
const FILE_NAME_MAX = 120;
const MAX_FILES = 20;
const RELATED_MAX = 10;
const validFileName = (n) => typeof n === "string" && n.length <= FILE_NAME_MAX && FILE_NAME_RE.test(n);
const fileNameProblem = (n) => (validFileName(n) ? "" :
  `"${String(n).slice(0, 80)}" isn't a usable PDF name: use only letters, numbers, dots, hyphens and underscores, ending in .pdf (max ${FILE_NAME_MAX} characters).`);

/** A new resource id: 10 characters, a-z0-9 (lowercase: server.js lowercases paths). */
function newId() {
  const abc = "abcdefghijklmnopqrstuvwxyz0123456789";
  let id = "";
  for (const b of crypto.randomBytes(10)) id += abc[b % 36];
  return id;
}

/** "Círculo unitario: seno y coseno" -> "circulo-unitario-seno-y-coseno" (lowercase ASCII, hyphens). */
function slugify(text) {
  return String(text || "")
    .toLowerCase()
    .normalize("NFD").replace(/[̀-ͯ]/g, "")
    .replace(/ß/g, "ss").replace(/æ/g, "ae").replace(/ø/g, "o").replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, SLUG_MAX)
    .replace(/-+$/, "");
}

const validSlug = (s) => typeof s === "string" && s.length <= SLUG_MAX && SLUG_RE.test(s) && !RESERVED_SLUGS.has(s);

const str = (v, max = 20000) => (typeof v === "string" ? v.replace(/\r\n?/g, "\n").trim().slice(0, max) : "");
const list = (v, max = 30, each = 2000) => (Array.isArray(v) ? v : []).map((x) => str(x, each)).filter(Boolean).slice(0, max);

function normalizeText(t) {
  t = t && typeof t === "object" ? t : {};
  return {
    title: str(t.title, 200),
    description: str(t.description, 400),
    intro: str(t.intro),
    howTo: list(t.howTo),
    keyIdeas: list(t.keyIdeas),
    faq: (Array.isArray(t.faq) ? t.faq : [])
      .map((f) => ({ q: str(f && f.q, 400), a: str(f && f.a, 4000) }))
      .filter((f) => f.q || f.a)
      .slice(0, 12),
    keywords: list(t.keywords, 30, 80),
  };
}

/** Every field present, with defaults (so later phases can add fields without a migration). */
function normalize(doc) {
  const d = doc && typeof doc === "object" ? doc : {};
  return {
    id: String(d.id || ""),
    status: STATUSES.includes(d.status) ? d.status : "draft",
    visibility: typeof d.visibility === "string" && d.visibility ? d.visibility : "public",
    slugEn: str(d.slugEn, SLUG_MAX),
    slugEs: str(d.slugEs, SLUG_MAX),
    slugHistoryEn: list(d.slugHistoryEn, 50, SLUG_MAX),
    slugHistoryEs: list(d.slugHistoryEs, 50, SLUG_MAX),
    en: normalizeText(d.en),
    es: normalizeText(d.es),
    subject: SUBJECTS[d.subject] ? d.subject : "other",
    levels: list(d.levels, 3, 20).filter((l) => LEVELS[l]),
    courseTags: list(d.courseTags, 20, 60),
    relatedExamPage: EXAM_LINKS.some((x) => x.en === d.relatedExamPage) ? d.relatedExamPage : "",
    file: d.file && typeof d.file === "object" && d.file.version ? {
      path: String(d.file.path || ""),
      version: Number(d.file.version) || 0,
      sizeBytes: Number(d.file.sizeBytes) || 0,
      sha256: String(d.file.sha256 || ""),
      uploadedAt: String(d.file.uploadedAt || ""),
      warnings: list(d.file.warnings, 30, 400),
      name: str(d.file.name, 200), // the uploaded file's name (to pair it with a config file)
    } : null,
    // every config JSON uploaded, original bytes kept in the bucket (resources/<id>/config-<n>.json)
    configs: (Array.isArray(d.configs) ? d.configs : []).filter((c) => c && c.path).slice(-50).map((c) => ({
      n: Number(c.n) || 0, path: String(c.path), name: str(c.name, 200), file: str(c.file, 200),
      fileVersion: Number(c.fileVersion) || 0, sizeBytes: Number(c.sizeBytes) || 0, uploadedAt: String(c.uploadedAt || ""),
    })),
    // PDFs, in display order. path "" = listed (by a config or the editor) but not uploaded yet.
    files: normalizeFiles(d.files),
    // EN slugs of resources to show first under "Related resources", in order
    related: list(d.related, RELATED_MAX, SLUG_MAX).map((x) => x.toLowerCase()).filter((x) => SLUG_RE.test(x)),
    og: { en: str(d.og && d.og.en, 200), es: str(d.og && d.og.es, 200) },
    // +1 on every save; a save from the editor carries the number it was loaded at (stale -> refused)
    rev: Math.max(0, Math.floor(Number(d.rev) || 0)),
    createdAt: String(d.createdAt || ""),
    publishedAt: String(d.publishedAt || ""),
    updatedAt: String(d.updatedAt || ""),
    checkedAt: String(d.checkedAt || ""),
  };
}

function normalizeFiles(v) {
  const seen = new Set(), out = [];
  for (const f of Array.isArray(v) ? v : []) {
    if (!f || typeof f !== "object" || !validFileName(f.name) || seen.has(f.name.toLowerCase())) continue;
    seen.add(f.name.toLowerCase());
    const up = !!f.path;
    out.push({
      name: f.name, labelEn: str(f.labelEn, 200), labelEs: str(f.labelEs, 200),
      path: up ? String(f.path) : "", sizeBytes: up ? Number(f.sizeBytes) || 0 : 0,
      sha256: up ? String(f.sha256 || "") : "", uploadedAt: up ? String(f.uploadedAt || "") : "",
    });
    if (out.length >= MAX_FILES) break;
  }
  return out;
}

/** The slug of a resource in a language, and its old slugs. */
const slugOf = (doc, lang) => (lang === "es" ? doc.slugEs : doc.slugEn);
const historyOf = (doc, lang) => (lang === "es" ? doc.slugHistoryEs : doc.slugHistoryEn) || [];
const pathOf = (doc, lang) => `${BASE[lang]}${slugOf(doc, lang)}/`;
const filePath = (id, version) => `resources/${id}/v${version}.html`;
const pdfPath = (id, name) => `resources/${id}/files/${name}`;
/** The public URL of an attached file: always the EN slug (the Spanish page links to the same URL). */
const fileUrl = (doc, name) => `${BASE.en}${doc.slugEn}/files/${name}`;
/** Files that can be shown and served (uploaded), in order. */
const uploadedFiles = (doc) => (doc.files || []).filter((f) => f.path);
const isLive = (doc) => doc.status === "published" && doc.visibility === "public";

/**
 * What's missing before a resource can be published, in plain words ([] = ready).
 * `others` = every other resource (for slug uniqueness).
 */
function problems(doc, others = []) {
  const out = [];
  if (!doc.file || !doc.file.version) out.push("Upload the tool's HTML file.");
  for (const lang of LANGS) {
    const L = lang.toUpperCase(), t = doc[lang];
    if (!t.title) out.push(`${L}: title is required.`);
    if (!t.description) out.push(`${L}: description is required.`);
    else if (t.description.length > DESC_MAX) out.push(`${L}: description is ${t.description.length} characters (max ${DESC_MAX}).`);
    if (!t.intro) out.push(`${L}: intro is required.`);
    if (!t.howTo.length) out.push(`${L}: add at least one "how to use it" step.`);
    if (!t.keyIdeas.length) out.push(`${L}: add at least one key idea.`);
    for (const f of t.faq) if (!f.q || !f.a) out.push(`${L}: every FAQ item needs a question and an answer.`);
  }
  if (!doc.levels.length) out.push("Pick at least one level.");
  for (const f of doc.files || []) {
    if (!f.path) out.push(`PDF ${f.name} is listed but not uploaded. Drop it, or remove it from Files.`);
    if (!f.labelEn || !f.labelEs) out.push(`PDF ${f.name} needs an EN and an ES label.`);
  }
  out.push(...slugProblems(doc, others));
  return [...new Set(out)];
}

/** Slug errors only: format, and uniqueness against every other resource's current and old slugs. */
function slugProblems(doc, others = []) {
  const out = [];
  for (const lang of LANGS) {
    const s = slugOf(doc, lang), L = lang.toUpperCase();
    if (!s) { out.push(`${L}: slug is required.`); continue; }
    if (!validSlug(s)) { out.push(`${L}: slug "${s}" must be lowercase letters, numbers and hyphens${RESERVED_SLUGS.has(s) ? ` (and "${s}" is reserved)` : ""}.`); continue; }
    const taken = others.find((o) => o.id !== doc.id && (slugOf(o, lang) === s || historyOf(o, lang).includes(s)));
    if (taken) out.push(`${L}: slug "${s}" is already used by "${taken[lang].title || taken.id}".`);
  }
  return out;
}

/**
 * Applies a save from the admin: when a resource that was ever published changes slug, the old slug
 * goes into its history (-> 301). A slug that comes back is taken out of the history.
 */
function applySlugChange(before, after) {
  const out = { ...after };
  for (const lang of LANGS) {
    const key = lang === "es" ? "slugEs" : "slugEn", hk = lang === "es" ? "slugHistoryEs" : "slugHistoryEn";
    let hist = [...(before[hk] || [])];
    if (before.publishedAt && before[key] && after[key] && before[key] !== after[key] && !hist.includes(before[key])) hist.push(before[key]);
    hist = hist.filter((s) => s !== after[key]);
    out[hk] = hist;
  }
  return out;
}

/** Newest first (publishedAt, then updatedAt). */
const newest = (docs) => [...docs].sort((a, b) => String(b.publishedAt || b.updatedAt).localeCompare(String(a.publishedAt || a.updatedAt)));

/**
 * "Related resources" for a page, up to `max` (default 3), from the cached list only:
 *   1. the resource's own `related` EN slugs, in order (current or old slug of the target);
 *   2. reverse links: resources whose `related` names this one (by its current or an old EN slug),
 *      newest first;
 *   3. resources sharing at least one course tag (case-insensitive), most shared first, then newest;
 *   4. the same subject, newest first.
 * Published resources only; never the resource itself; no repeats.
 */
function relatedFor(doc, all, max = 3) {
  const live = newest(all.filter((d) => isLive(d) && d.id !== doc.id));
  const out = [], seen = new Set();
  const take = (d) => { if (d && !seen.has(d.id) && out.length < max) { seen.add(d.id); out.push(d); } };
  // 1. own list
  for (const s of doc.related || []) take(live.find((d) => d.slugEn === s) || live.find((d) => historyOf(d, "en").includes(s)));
  // 2. reverse links
  const names = new Set([doc.slugEn, ...historyOf(doc, "en")].filter(Boolean));
  live.filter((d) => (d.related || []).some((s) => names.has(s))).forEach(take);
  // 3. shared course tags
  const tags = new Set((doc.courseTags || []).map((t) => t.toLowerCase()));
  const shared = (d) => (d.courseTags || []).filter((t) => tags.has(t.toLowerCase())).length;
  if (tags.size) {
    live.map((d) => [d, shared(d)]).filter(([, n]) => n > 0)
      .sort((a, b) => b[1] - a[1]) // stable: newest first within the same count
      .forEach(([d]) => take(d));
  }
  // 4. same subject
  live.filter((d) => d.subject === doc.subject).forEach(take);
  return out;
}

module.exports = {
  SITE, LANGS, BASE, SUBJECTS, LEVELS, EXAM_LINKS, STATUSES, VISIBILITIES, RESERVED_SLUGS, DESC_MAX, SLUG_MAX, SLUG_RE, ID_RE,
  FILE_NAME_RE, FILE_NAME_MAX, MAX_FILES, RELATED_MAX, validFileName, fileNameProblem,
  newId, slugify, validSlug, normalize, normalizeFiles, slugOf, historyOf, pathOf, filePath, pdfPath, fileUrl, uploadedFiles,
  isLive, problems, slugProblems, applySlugChange, relatedFor, newest,
};
